from dataclasses import dataclass

SURVIVAL_NEIGHBOR_COUNTS = (2, 3)
REPRODUCTION_NEIGHBOR_COUNT = 3


@dataclass(frozen=True)
class Cell:
    x: int
    y: int


def next_generation(living_cells):
    return [
        cell
        for cell in _candidate_cells(living_cells)
        if _lives_on(cell, living_cells)
    ]


def _candidate_cells(living_cells):
    candidates = []
    for cell in living_cells:
        for neighbor in _neighbors_of(cell):
            if neighbor not in candidates:
                candidates.append(neighbor)
        if cell not in candidates:
            candidates.append(cell)
    return candidates


def _neighbors_of(cell):
    return [
        Cell(cell.x + dx, cell.y + dy)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        if (dx, dy) != (0, 0)
    ]


def _lives_on(cell, living_cells):
    neighbor_count = _living_neighbor_count(cell, living_cells)
    if cell in living_cells:
        return neighbor_count in SURVIVAL_NEIGHBOR_COUNTS
    return neighbor_count == REPRODUCTION_NEIGHBOR_COUNT


def _living_neighbor_count(cell, living_cells):
    return sum(1 for other in living_cells if _are_neighbors(cell, other))


def _are_neighbors(cell, other):
    return cell != other and abs(cell.x - other.x) <= 1 and abs(cell.y - other.y) <= 1
